Metadata.StatusCode value = Metadata.StatusCode.APEX_FAILED;
Metadata.StatusCode other = Metadata.StatusCode.INTERNAL_ERROR;
System.assert(value.equals(value));
System.assert(!value.equals(other));
System.assert(!value.equals(null));
System.assertNotEquals(value.hashCode(), other.hashCode());
System.assertNotEquals(value.ordinal(), other.ordinal());
System.assertEquals(value.ordinal(), Metadata.StatusCode.valueOf('APEX_FAILED').ordinal());
System.assertEquals(other.ordinal(), Metadata.StatusCode.valueOf('INTERNAL_ERROR').ordinal());
System.assertEquals(value, Metadata.StatusCode.valueOf('APEX_FAILED'));
System.assertEquals(other, Metadata.StatusCode.valueOf('INTERNAL_ERROR'));
List<Metadata.StatusCode> values = Metadata.StatusCode.values();
System.assertEquals(513, values.size());
System.assertEquals(value, values[value.ordinal()]);
System.assertEquals(other, values[other.ordinal()]);

